/* From Uiverse.io by garerim - Tags: input, search */
.__UIV_SCOPE__ .container-input {
  position: relative;
}

.__UIV_SCOPE__ .input {
  width: 150px;
  padding: 10px 0px 10px 40px;
  border-radius: 9999px;
  border: solid 1px #333;
  transition: all .2s ease-in-out;
  outline: none;
  opacity: 0.8;
}

.__UIV_SCOPE__ .container-input svg {
  position: absolute;
  top: 50%;
  left: 10px;
  transform: translate(0, -50%);
}

.__UIV_SCOPE__ .input:focus {
  opacity: 1;
  width: 250px;
}
